{"implementation": "def solve(case):
    if "nodes" not in case or "core_distance" not in case or "distances" not in case:
        raise ValueError("Missing required fields: nodes, core_distance, distances")
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances_raw = case["distances"]
    n = len(nodes)
    if n == 0:
        raise ValueError("nodes list is empty")
    node_set = set(nodes)
    for node in nodes:
        if node not in core_distance:
            raise ValueError("Missing core distance for node: " + str(node))
    edges = []
    for entry in distances_raw:
        if len(entry) != 3:
            raise ValueError("Each distance entry must have exactly 3 elements")
        u, v, d = entry[0], entry[1], float(entry[2])
        if u not in node_set or v not in node_set:
            raise ValueError("Edge references unknown node")
        if u > v:
            u, v = v, u
        mr = max(core_distance[u], core_distance[v], d)
        edges.append((mr, u, v))
    edges.sort(key=lambda e: (e[0], e[1], e[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for mr, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError("Input graph is disconnected; cannot form a spanning tree")
    return {"mst_edges": mst_edges, "total_weight": total_weight}"}
